const envelope = $input.first().json;
const payload = envelope.body ?? envelope;
if (!payload || payload.schemaVersion !== 1 || !payload.dashboard) {
  throw new Error('invalid snapshot envelope');
}
if (!Array.isArray(payload.dashboard.views) || payload.dashboard.views.length !== 3) {
  throw new Error('invalid dashboard views');
}
if (!Array.isArray(payload.dashboard.metrics) || payload.dashboard.metrics.length !== 15) {
  throw new Error('invalid dashboard metrics');
}
if (payload.ranking && (!Array.isArray(payload.ranking.participants) || payload.ranking.participants.length > 2000)) {
  throw new Error('invalid ranking participants');
}
const serialized = JSON.stringify(payload).toLowerCase();
const forbidden = ['cpf', 'cnpj', 'password', 'senha', 'bank', 'banco', 'agência bancária', 'conta bancária', 'telefone', 'phone', 'email', 'logradouro', 'cep'];
if (forbidden.some((field) => serialized.includes(`\"${field}\"`))) {
  throw new Error('forbidden source field');
}
return [{ json: { payload, accepted: true } }];
